def commonExtension(s, queries):
    MOD = (1 << 61) - 1
    B = 911382323
    n = len(s)
    H = [0] * (n + 1)
    PW = [1] * (n + 1)
    for i, c in enumerate(s):
        H[i + 1] = (H[i] * B + ord(c)) % MOD
        PW[i + 1] = PW[i] * B % MOD
    res = []
    for i, j in queries:
        lo, hi = 0, n - max(i, j)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if (H[i + mid] - H[i] * PW[mid]) % MOD == (H[j + mid] - H[j] * PW[mid]) % MOD:
                lo = mid
            else:
                hi = mid - 1
        res.append(lo)
    return res
